#!/bin/bash
# Download all pre-existing artifacts needed for this environment.
#
# Run on a node with internet access BEFORE submitting compute jobs.
# Idempotent: files that already exist are skipped.
#
# Estimated total download size: ~0.7 MB
# Estimated disk usage after extraction: ~0.7 MB
#
# The only external artifact is the pair of 1D denoisers released by the
# paper's authors (https://github.com/zhengqigao/REG, 1d-toy/models), used as
# the `paper_checkpoint` training problem.  Everything else (public training
# problems, hidden test problems) is generated by code in this repository and
# committed (data/toy_1d_train/, eval/test/assets/).

set -euo pipefail

cd /home/user

DEST=data/downloads/paper_ckpt
BASE=https://raw.githubusercontent.com/zhengqigao/REG/main/1d-toy/models
NAME=diffusion_model_e200_numstep20_seed0_s0.0001_e0.02_dim128_layer3
mkdir -p "$DEST"

fetch() {  # fetch <remote-file> <local-file> <sha256>
    if [ -s "$2" ] && echo "$3  $2" | sha256sum -c --status; then
        echo "present: $2"
        return
    fi
    curl -fsSL --retry 3 -o "$2.part" "$BASE/$1"
    echo "$3  $2.part" | sha256sum -c --status || { echo "checksum mismatch for $1" >&2; rm -f "$2.part"; exit 1; }
    mv "$2.part" "$2"
    echo "downloaded: $2"
}

fetch "${NAME}_cond.pth"   "$DEST/cond.pth"   30ade5604a449176267518d1b417e1912049b5d9f9174abbef21de11747960f6
fetch "${NAME}_uncond.pth" "$DEST/uncond.pth" 36dad1efa88e45887e9ca7e42733a2c3832f5c4815b34efe53b21e4d691fb962
